#!/usr/bin/env python3
"""Read-only checks for declared routes; this is not a runtime skill loader."""

import argparse
import json
import os
from pathlib import Path
import re
import subprocess

VARIANT = "kc-dev-flow-2"
STAGES = ("ideation", "implementation", "validation")
PROFILES = ("poc", "pilot", "prod")
AGENT_MODELS = {"engineering-reviewer": ("opus", "xhigh"), "chief-engineer": ("opus", "xhigh"),
                "observer": ("sonnet", "high")}
DEFAULT_ROOT = Path(__file__).resolve().parents[1]
BASIC_LINT = DEFAULT_ROOT.parent / "scripts/skill-frontmatter-lint.sh"
LINK = re.compile(r"\[[^\]]+\]\(([^)]+)\)")
NAMESPACE = re.compile(r"\bkc-dev-flow(?:-[a-z0-9]+)*:[a-z0-9-]+\b")
PACKAGE_ROOT = re.compile(r"^Package root: \S", re.MULTILINE)
UNBOUND_ROOT = re.compile(r"\{package\}|/absolute/plugin")
WORKFLOW = "references/sd/workflow.md"
CAPTAIN_QUOTE = re.compile(r"「[^」]*\S[^」]*」")
# The budget is START plus the deltas, so the README count must equal it and a cut lowers it in the same change.
# A raise (delta > 0) needs the Captain's quoted words and the one moment FO reads the added text.
WORKFLOW_BUDGET_START = 5511
WORKFLOW_BUDGET_STEPS = [
    dict(delta=-64, why="dispatch_records.py and design_surfaces.py print the parts and defects; the README points to them"),
    dict(delta=-18, why="delivery_gate.py prints the hold and ask lines; the README points to it"),
]
DUPLICATE_RUN = 12
# Known overlaps awaiting a decision on which copy survives, keyed by file and opening words.
KNOWN_DUPLICATES = {
    ("skills/ideation/principles.md", "ideation writes no repository file branch or commit"),
    # FO reads the workflow copy before presenting the gate; the validation worker reads its own.
    ("skills/validation/principles.md", "validation runs python3 <package>/scripts/adr_lint.py"),
    # The workflow copy stays for FO (Delivery authority); workers no longer receive that section.
    ("skills/implementation/principles.md", "do not invoke local fallback push the trunk"),
    ("skills/validation/principles.md", "do not invoke local fallback push the trunk"),
}
BOUND_SCRIPT_DIR = re.compile(r"(?:<package>/|(?:\.\./)+|kc-dev-flow-2/)scripts/")


def lint_tree(root, basic_lint=BASIC_LINT):
    """Validate the scaffold's declared schema, without interpreting rule prose."""
    root = Path(root).resolve()
    errors = []

    def read(path):
        try:
            if not path.resolve().is_relative_to(root):
                raise ValueError("reference escapes the variant tree")
            text = path.read_text(encoding="utf-8")
            if not text.strip():
                raise ValueError("empty required file")
            return text
        except (OSError, ValueError) as exc:
            errors.append(f"{path.relative_to(root)}: {exc}")
            return ""

    if not root.is_dir():
        return [f"variant directory missing: {root}"]
    if not Path(basic_lint).is_file():
        errors.append(f"repository frontmatter check missing: {basic_lint}")
    else:
        result = subprocess.run(
            ["bash", str(basic_lint)],
            env={**os.environ, "REPO_DIR_OVERRIDE": str(root)},
            capture_output=True, text=True, check=False,
        )
        if result.returncode:
            errors.append("frontmatter: " + (result.stderr or result.stdout).strip())

    skills = {p.name for p in (root / "skills").glob("*") if p.is_dir()}
    required = set(STAGES + tuple(AGENT_MODELS) + ("maintain-flow",))
    if missing := required - skills:
        errors.append("missing skills: " + ", ".join(sorted(missing)))
    read(root / "README.md")
    for skill in sorted(skills):
        path = root / "skills" / skill / "SKILL.md"
        body = read(path)
        calls = re.findall(r"^Invocation: `([^`]+)`$", body, re.MULTILINE)
        if calls != [f"{VARIANT}:{skill}"]:
            errors.append(f"{skill}: expected one exact variant Invocation")
    for path in sorted(root.rglob("*.md")):
        for call in NAMESPACE.findall(read(path)):
            if call not in {f"{VARIANT}:{skill}" for skill in skills}:
                errors.append(f"{path.relative_to(root)}: unknown variant skill {call}")

    homes = {p.name: ("scripts/", BOUND_SCRIPT_DIR) for p in (root / "scripts").glob("*") if p.suffix in (".py", ".sh")}
    for p in (root / "extensions").glob("*/*"):
        if p.suffix in (".py", ".sh"):
            home = f"extensions/{p.parent.name}/"
            homes[p.name] = (home, re.compile(r"(?:<package>/|kc-dev-flow-2/)" + re.escape(home)))
    names = sorted(homes, key=len, reverse=True)
    script = re.compile(r"(?P<dir>[^\s`'\"(\[]*(?:scripts|extensions/[\w-]+)/)?(?<![\w-])(?P<name>"
                        + "|".join(map(re.escape, names)) + r")(?![\w-])")
    docs = [*(root / "skills").rglob("*.md"), *(root / "references").rglob("*.md"), *(root / "extensions").rglob("*.md")]
    for path in sorted(docs):
        text = read(path)
        where = path.relative_to(root)
        if UNBOUND_ROOT.search(text):
            errors.append(f"{where}: package path must be <package>/scripts/NAME, not {{package}} or /absolute/plugin")
        for match in script.finditer(text):
            home, bound = homes[match["name"]]
            if not (match["dir"] and bound.fullmatch(match["dir"])):
                errors.append(f"{where}: script {match['name']} is named without <package>/{home}")
    for folder in sorted((root / "skills").glob("*")):
        if any("<package>" in read(md) for md in folder.rglob("*.md")) and not PACKAGE_ROOT.search(
                read(folder / "SKILL.md")):
            errors.append(f"skills/{folder.name}/SKILL.md: uses <package> but has no 'Package root:' line")

    for stage in STAGES:
        folder = root / "skills" / stage
        body = read(folder / "SKILL.md")
        read(folder / "principles.md")
        if "principles.md" not in LINK.findall(body):
            errors.append(f"{stage}: missing link to stage principles.md")
        start, end = "<!-- profile-routes -->", "<!-- /profile-routes -->"
        if (body.count(start) != 1 or body.count(end) != 1
                or body.index(start) >= body.index(end)):
            errors.append(f"{stage}: expected one ordered profile routing table")
            continue
        table = body.split(start)[1].split(end)[0].strip().splitlines()
        header = "| Profile | Availability | Profile principles | Stage reference |"
        if len(table) < 3 or table[0] != header:
            errors.append(f"{stage}: invalid profile table columns")
            continue
        separator = [cell.strip() for cell in table[1].strip().strip("|").split("|")]
        if len(separator) != 4 or not all(re.fullmatch(r":?-{3,}:?", cell) for cell in separator):
            errors.append(f"{stage}: invalid profile table separator")
            continue
        rows = {}
        for line in table[2:]:
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) != 4 or cells[0] not in PROFILES:
                errors.append(f"{stage}: invalid profile row {line}")
                continue
            profile, availability, shared, specific = cells
            if profile in rows:
                errors.append(f"{stage}: duplicate profile {profile}")
            rows[profile] = True
            expected = "skip" if (stage, profile) == ("ideation", "poc") else "active"
            if availability != expected:
                errors.append(f"{stage}/{profile}: availability must be {expected}")
            for cell, target in (
                (shared, root / "references/profiles" / f"{profile}.md"),
                (specific, folder / "profiles" / f"{profile}.md"),
            ):
                match = LINK.fullmatch(cell)
                if not match or (folder / match[1]).resolve() != target:
                    errors.append(f"{stage}/{profile}: route must link to {target.relative_to(root)}")
                read(target)
        if set(rows) != set(PROFILES):
            errors.append(f"{stage}: profile coverage must be poc, pilot, prod")

    for role, policy in AGENT_MODELS.items():
        body = read(root / "agents" / f"{role}.md")
        fields = dict(re.findall(r"^(skills|model|reasoning): (.+)$", body, re.MULTILINE))
        try:
            calls = json.loads(fields.get("skills", "null"))
        except json.JSONDecodeError:
            calls = None
        if calls != [f"{VARIANT}:{role}"]:
            errors.append(f"{role} agent: expected exact variant skill binding")
        if (fields.get("model"), fields.get("reasoning")) != policy:
            errors.append(f"{role} agent: existing {policy[0]}/{policy[1]} policy changed")
    errors += workflow_size_and_duplicates(root)
    return errors


def normalized_words(text):
    return re.findall(r"[a-z0-9<>/_.\-]+", text.lower().replace("`", ""))


def workflow_budget(steps=None):
    steps = WORKFLOW_BUDGET_STEPS if steps is None else steps
    return WORKFLOW_BUDGET_START + sum(step["delta"] for step in steps)


def budget_errors(count, steps=None):
    steps = WORKFLOW_BUDGET_STEPS if steps is None else steps
    errors = []
    for index, step in enumerate(steps):
        where = f"{WORKFLOW}: WORKFLOW_BUDGET_STEPS[{index}]"
        if not str(step.get("why", "")).strip():
            errors.append(f"{where} has no 'why'")
        if step["delta"] > 0:
            if not CAPTAIN_QUOTE.search(str(step.get("captain", ""))):
                errors.append(f"{where} raises the budget by {step['delta']} and its 'captain' has no quoted words")
            if not str(step.get("loaded", "")).strip():
                errors.append(f"{where} raises the budget by {step['delta']} and has no 'loaded' moment")
    budget = workflow_budget(steps)
    if count > budget:
        errors.append(f"{WORKFLOW}: {count} words exceeds the budget of {budget}; move the added text out of the README, "
                      f"or add a raise step of {count - budget} with 'captain' and 'loaded' to WORKFLOW_BUDGET_STEPS")
    elif count < budget:
        errors.append(f"{WORKFLOW}: {count} words is {budget - count} under the budget of {budget}; "
                      f"add a cut step of {count - budget} with a 'why' to WORKFLOW_BUDGET_STEPS")
    return errors


def workflow_size_and_duplicates(root):
    path = root / WORKFLOW
    if not path.is_file():
        return [f"{WORKFLOW}: missing"]
    text = path.read_text()
    errors = budget_errors(len(text.split()))
    words = normalized_words(text)
    runs = {" ".join(words[i:i + DUPLICATE_RUN]) for i in range(len(words) - DUPLICATE_RUN + 1)}
    others = set(root.glob("skills/**/*.md")) | set(root.glob("references/**/*.md")) | set(root.glob("agents/*.md"))
    for other in sorted(others):
        relative = str(other.relative_to(root))
        if relative == WORKFLOW:
            continue
        theirs = normalized_words(other.read_text())
        i = 0
        while i <= len(theirs) - DUPLICATE_RUN:
            if " ".join(theirs[i:i + DUPLICATE_RUN]) not in runs:
                i += 1
                continue
            end = i + DUPLICATE_RUN
            while end < len(theirs) and " ".join(theirs[end - DUPLICATE_RUN + 1:end + 1]) in runs:
                end += 1
            passage = " ".join(theirs[i:end])
            if not any(relative == known and passage.startswith(opening) for known, opening in KNOWN_DUPLICATES):
                errors.append(f"{relative}: repeats {end - i} words of {WORKFLOW}: '{passage[:80]}'")
            i = end
    return errors


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=DEFAULT_ROOT,
                        help="variant tree to check; defaults to this scaffold")
    args = parser.parse_args()
    errors = lint_tree(args.root)
    if errors:
        for error in errors:
            print("FAIL:", error)
        return 1
    count = len((args.root / WORKFLOW).read_text().split())
    print("PASS: basic frontmatter, declared profile routes, role bindings and package script paths")
    print(f"{WORKFLOW}: {count} of {workflow_budget()} words; no unlisted passage repeats it")
    print("Not checked: full Agent Skills conformance or host/workflow behavior")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""Mutation checks on disposable copies of the static comparison scaffold."""

import importlib.util
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

sys.dont_write_bytecode = True
ROOT = Path(__file__).resolve().parents[1]
spec = importlib.util.spec_from_file_location("flow_lint", ROOT / "scripts/lint-skills.py")
lint = importlib.util.module_from_spec(spec)
spec.loader.exec_module(lint)
SHIPPED = list(lint.WORKFLOW_BUDGET_STEPS)


class RouteMutationTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name) / "kc-dev-flow-2"
        shutil.copytree(ROOT, self.root)

    def change(self, relative, old, new):
        path = self.root / relative
        text = path.read_text()
        self.assertIn(old, text, "mutation must actually change its fixture")
        path.write_text(text.replace(old, new, 1))

    def refuses(self, expected):
        errors = lint.lint_tree(self.root)
        self.assertTrue(any(expected in error for error in errors), errors)

    def test_valid_scaffold(self):
        self.assertEqual(lint.lint_tree(self.root), [])

    def test_missing_profile_reference(self):
        (self.root / "skills/implementation/profiles/pilot.md").unlink()
        self.refuses("profiles/pilot.md")

    def test_cross_profile_route(self):
        self.change("skills/implementation/SKILL.md", "(profiles/poc.md)", "(profiles/prod.md)")
        self.refuses("route must link to skills/implementation/profiles/poc.md")

    def test_cross_stage_route(self):
        self.change("skills/validation/SKILL.md", "(profiles/pilot.md)", "(../implementation/profiles/pilot.md)")
        self.refuses("route must link to skills/validation/profiles/pilot.md")

    def test_wrong_shared_principle(self):
        self.change("skills/ideation/SKILL.md", "../../references/profiles/pilot.md", "../../references/profiles/prod.md")
        self.refuses("route must link to references/profiles/pilot.md")

    def test_unknown_profile(self):
        self.change("skills/implementation/SKILL.md", "| poc | active |", "| experimental | active |")
        self.refuses("profile coverage")

    def test_duplicate_profile(self):
        self.change("skills/implementation/SKILL.md", "| pilot | active |", "| poc | active |")
        self.refuses("duplicate profile")

    def test_missing_markdown_table_separator(self):
        self.change("skills/implementation/SKILL.md", "| --- | --- | --- | --- |", "Plain prose is not a table separator.")
        self.refuses("invalid profile table separator")

    def test_reversed_routing_markers(self):
        relative = "skills/implementation/SKILL.md"
        self.change(relative, "<!-- profile-routes -->", "<!-- temporary-marker -->")
        self.change(relative, "<!-- /profile-routes -->", "<!-- profile-routes -->")
        self.change(relative, "<!-- temporary-marker -->", "<!-- /profile-routes -->")
        self.refuses("expected one ordered profile routing table")

    def test_poc_cannot_declare_ideation_active(self):
        self.change("skills/ideation/SKILL.md", "| poc | skip |", "| poc | active |")
        self.refuses("availability must be skip")

    def test_missing_principles(self):
        (self.root / "skills/validation/principles.md").unlink()
        self.refuses("validation/principles.md")

    def test_external_reference_symlink(self):
        target = self.root / "references/profiles/poc.md"
        outside = self.root.parent / "external.md"
        target.rename(outside)
        target.symlink_to(outside)
        self.refuses("reference escapes the variant tree")

    def test_old_variant_invocation(self):
        self.change("skills/chief-engineer/SKILL.md", "kc-dev-flow-2:engineering-reviewer", "kc-dev-flow:science-officer")
        self.refuses("unknown variant skill")

    def test_role_binding_and_model_policy(self):
        self.change("agents/engineering-reviewer.md", "model: opus", "model: inherit")
        self.change("agents/chief-engineer.md", '["kc-dev-flow-2:chief-engineer"]', '["kc-dev-flow:chief-engineer"]')
        self.refuses("opus/xhigh policy changed")
        self.refuses("expected exact variant skill binding")

    def test_observer_keeps_its_declared_model(self):
        self.change("agents/observer.md", "model: sonnet", "model: inherit")
        self.refuses("observer agent: existing sonnet/high policy changed")

    def test_bare_script_name(self):
        self.change("skills/implementation/principles.md", "<package>/scripts/comment_ratio.py", "comment_ratio.py")
        self.refuses("skills/implementation/principles.md: script comment_ratio.py is named without")

    def test_script_named_by_link_label_only(self):
        self.change("skills/learn/SKILL.md", "[learning recorder]", "[learning.py]")
        self.refuses("skills/learn/SKILL.md: script learning.py is named without")

    def test_extension_script_named_without_its_extension_path(self):
        self.change("extensions/roborev/EXTENSION.md", "<package>/extensions/roborev/roborev_gate.py", "<package>/scripts/roborev_gate.py")
        self.refuses("extensions/roborev/EXTENSION.md: script roborev_gate.py is named without <package>/extensions/roborev/")

    def test_machine_path_placeholder(self):
        self.change("skills/learn/SKILL.md", "<package>/scripts/learning.py --repo \"$CODE_ROOT\" release",
                    "/absolute/plugin/scripts/learning.py --repo \"$CODE_ROOT\" release")
        self.refuses("skills/learn/SKILL.md: package path must be <package>/scripts/NAME")

    def test_brace_placeholder(self):
        self.change("references/sd/adoption.md", "python3 <package>/scripts/poc_readme.py derive",
                    "python3 {package}/scripts/poc_readme.py derive")
        self.refuses("references/sd/adoption.md: package path must be <package>/scripts/NAME")

    def test_package_placeholder_without_root_line(self):
        self.change("skills/implementation/SKILL.md", "Package root: ${CLAUDE_PLUGIN_ROOT}\n", "")
        self.refuses("skills/implementation/SKILL.md: uses <package> but has no 'Package root:' line")

    def workflow_text(self):
        return (self.root / "references/sd/workflow.md").read_text()

    def with_words(self, delta):
        path = self.root / "references/sd/workflow.md"
        text = path.read_text()
        path.write_text(text + "\nfiller" * delta if delta > 0 else text.rsplit(None, -delta)[0] + "\n")
        return len(path.read_text().split())

    def budget_with(self, steps):
        patch = mock.patch.object(lint, "WORKFLOW_BUDGET_STEPS", steps)
        patch.start()
        self.addCleanup(patch.stop)

    def test_workflow_over_its_word_budget(self):
        self.with_words(lint.workflow_budget(SHIPPED) - len(self.workflow_text().split()) + 1)
        self.refuses(f"exceeds the budget of {lint.workflow_budget()}")
        self.refuses("raise step")

    def test_workflow_under_its_word_budget_names_the_cut_step(self):
        self.with_words(-1)
        self.refuses(f"is 1 under the budget of {lint.workflow_budget()}")
        self.refuses("cut step of -1")

    def test_workflow_equal_to_its_word_budget_passes_and_prints_the_count(self):
        self.assertEqual(len(self.workflow_text().split()), lint.workflow_budget())
        result = subprocess.run([sys.executable, "-B", str(ROOT / "scripts/lint-skills.py"), "--root", str(self.root)],
                                capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stdout)
        n = lint.workflow_budget()
        self.assertIn(f"{n} of {n} words", result.stdout)

    def test_a_raise_step_needs_the_captains_quoted_words_and_a_loaded_moment(self):
        count = self.with_words(7)
        base = SHIPPED
        raised = dict(delta=count - lint.workflow_budget(SHIPPED), why="a rule FO reads only at startup")
        full = dict(raised, captain="\u300cthe added text is read once\u300d (chat)", loaded="startup")
        cases = {
            "no captain": (dict(raised, loaded="startup"), "'captain' has no quoted words"),
            "captain without a quote": (dict(raised, captain="approved", loaded="startup"), "'captain' has no quoted words"),
            "empty quote": (dict(raised, captain="\u300c \u300d", loaded="startup"), "'captain' has no quoted words"),
            "no loaded": (dict(raised, captain="\u300cyes\u300d"), "has no 'loaded' moment"),
        }
        for label, (step, expected) in cases.items():
            with self.subTest(label):
                self.budget_with([*base, step])
                errors = lint.lint_tree(self.root)
                self.assertTrue(any(expected in e and f"WORKFLOW_BUDGET_STEPS[{len(base)}]" in e for e in errors), errors)
        self.budget_with([*base, full])
        self.assertEqual(lint.lint_tree(self.root), [])

    def test_a_cut_step_needs_only_a_reason_and_a_step_without_one_is_refused(self):
        count = self.with_words(-3)
        cut = dict(delta=count - lint.workflow_budget(SHIPPED), why="moved to a script message")
        self.budget_with([*SHIPPED, cut])
        self.assertEqual(lint.lint_tree(self.root), [])
        self.budget_with([*SHIPPED, dict(delta=cut["delta"])])
        self.refuses("has no 'why'")

    def test_a_ledger_whose_sum_differs_from_the_count_is_refused_either_way(self):
        for drift in (1, -1):
            with self.subTest(drift):
                self.budget_with([*SHIPPED, dict(delta=drift, why="x", captain="\u300cx\u300d", loaded="x")])
                self.refuses("under the budget" if drift > 0 else "exceeds the budget")

    def test_a_passage_copied_from_the_workflow_into_another_file(self):
        source = (self.root / "references/sd/workflow.md").read_text()
        passage = " ".join(source.split("## Affected documents", 1)[1].split()[:20])
        path = self.root / "skills/validation/principles.md"
        path.write_text(path.read_text() + "\n" + passage.upper() + "\n")
        self.refuses("skills/validation/principles.md: repeats")

    def test_the_known_overlap_is_listed_and_a_new_one_is_not(self):
        self.assertEqual(lint.lint_tree(self.root), [])
        self.change("skills/implementation/principles.md", "\n", "\nIdeation writes no repository file, branch or commit; the design, the criteria and any ADR draft live in the task file.\n")
        self.refuses("skills/implementation/principles.md: repeats")

    def test_cli_exits_one_naming_the_file(self):
        self.change("skills/implementation/principles.md", "<package>/scripts/comment_ratio.py", "comment_ratio.py")
        result = subprocess.run([sys.executable, str(ROOT / "scripts/lint-skills.py"), "--root", str(self.root)],
                                capture_output=True, text=True)
        self.assertEqual(result.returncode, 1)
        self.assertIn("skills/implementation/principles.md", result.stdout)

    def test_existing_frontmatter_validator_is_used(self):
        path = self.root / "skills/validation/SKILL.md"
        body = path.read_text()
        description = next(line for line in body.splitlines() if line.startswith("description:"))
        path.write_text(body.replace(description, "description:", 1))
        self.refuses("frontmatter:")


if __name__ == "__main__":
    unittest.main(verbosity=2)
